    "content": "{\n  \"name\": \"viju-browser\",\n  \"productName\": \"Viju Browser\",\n  \"version\": \"1.4.0\",\n  \"description\": \"Custom security-hardened Windows desktop browser built with Electron and Chromium\",\n  \"main\": \"main.js\",\n  \"scripts\": {\n    \"start\": \"electron .\",\n    \"dev\": \"electron . --enable-logging\",\n    \"pack\": \"electron-builder --dir\",\n    \"dist:win\": \"electron-builder --win --x64 --publish never\",\n    \"release:github\": \"electron-builder --win --x64 --publish always\"\n  },\n  \"keywords\": [\n    \"browser\",\n    \"electron\",\n    \"chromium\",\n    \"privacy\",\n    \"webrtc-shield\",\n    \"auto-refresh\"\n  ],\n  \"author\": \"Viju Browser Engineering\",\n  \"license\": \"MIT\",\n  \"devDependencies\": {\n    \"electron\": \"^35.0.0\",\n    \"electron-builder\": \"^26.0.12\"\n  },\n  \"build\": {\n    \"appId\": \"com.vijubrowser.desktop\",\n    \"productName\": \"Viju Browser\",\n    \"directories\": {\n      \"output\": \"dist-installer\"\n    },\n    \"publish\": [\n      {\n        \"provider\": \"github\",\n        \"releaseType\": \"release\"\n      }\n    ],\n    \"files\": [\n      \"main.js\",\n      \"preload.js\",\n      \"tab-preload.js\",\n      \"ipc-validators.js\",\n      \"renderer.js\",\n      \"index.html\",\n      \"style.css\"\n    ],\n    \"win\": {\n      \"target\": [\n        {\n          \"target\": \"nsis\",\n          \"arch\": [\"x64\"]\n        },\n        {\n          \"target\": \"portable\",\n          \"arch\": [\"x64\"]\n        }\n      ]\n    },\n    \"nsis\": {\n      \"artifactName\": \"Viju-Browser-Setup-${version}-${arch}.${ext}\",\n      \"oneClick\": false,\n      \"allowToChangeInstallationDirectory\": true,\n      \"createDesktopShortcut\": true,\n      \"createStartMenuShortcut\": true,\n      \"shortcutName\": \"Viju Browser\"\n    },\n    \"portable\": {\n      \"artifactName\": \"Viju-Browser-Portable-${version}-${arch}.${ext}\"\n    }\n  }\n}\n"
